  #intro { position: fixed; inset: 0; background: #000; z-index: 10; transition: opacity .6s; }
  #intro video { width: 100%; height: 100%; object-fit: cover; }
  #intro .cap { position: absolute; left: 0; right: 0; bottom: 120px; text-align: center; font-size: 60px; font-weight: 800; text-shadow: 0 3px 18px rgba(0,0,0,.8); }
  #intro .tag { position: absolute; top: 40px; right: 48px; font-size: 24px; font-weight: 700; padding: 8px 16px; border-radius: 999px; background: rgba(0,0,0,.5); color: #cfe0ff; }
</style>
</head>
<body>
<div id="intro" hidden><video id="introVideo" muted playsinline></video><div class="cap" id="introCap"></div><div class="tag">AI-generated footage (Gemini)</div></div>
<div class="wrap">
  <section>
    <div class="brand"><b>Pawse</b> · calls the vet in German for you</div>
    <div class="clock" id="clock">Recorded live in the real app</div>
    <div class="caption" id="caption"></div>
    <div class="sub" id="sub"></div>
    <div class="badges" id="badges"></div>
